'use client';

import React, { useEffect, useState } from 'react';
import { WifiOff, RefreshCw, AlertTriangle } from 'lucide-react';
import { useLanguage } from '@/components/LanguageContext';

export default function OfflinePage() {
  const [checking, setChecking] = useState(false);
  const [isOnline, setIsOnline] = useState(false);
  const { t } = useLanguage();

  useEffect(() => {
    // Check initial online status
    if (typeof navigator !== 'undefined') {
      setIsOnline(navigator.onLine);
    }

    const goOnline = () => setIsOnline(true);
    const goOffline = () => setIsOnline(false);

    window.addEventListener('online', goOnline);
    window.addEventListener('offline', goOffline);

    return () => {
      window.removeEventListener('online', goOnline);
      window.removeEventListener('offline', goOffline);
    };
  }, []);

  const handleRetry = () => {
    setChecking(true);
    setTimeout(() => {
      setChecking(false);
      if (typeof navigator !== 'undefined' && navigator.onLine) {
        window.location.href = '/';
      } else {
        // Force reload page to trigger service worker retry check
        window.location.reload();
      }
    }, 1000);
  };

  return (
    <div className="min-h-screen bg-app text-main flex flex-col items-center justify-center p-6 relative overflow-hidden">
      {/* Background radial gradient */}
      <div className="absolute inset-0 bg-[radial-gradient(circle_at_center,rgba(37,99,235,0.08)_0%,transparent_60%)] pointer-events-none" />

      <div className="w-full max-w-md bg-card/60 backdrop-blur-xl border border-subtle rounded-3xl p-8 shadow-2xl relative z-10 text-center flex flex-col items-center">
        {/* Animated icon container */}
        <div className="w-20 h-20 bg-blue-500/10 rounded-full flex items-center justify-center border border-blue-500/20 mb-6 animate-pulse">
          <WifiOff className="w-10 h-10 text-blue-500" />
        </div>

        <h1 className="text-2xl font-black tracking-tight mb-2 text-main">
          {t('connection_lost')}
        </h1>
        
        <p className="text-secondary text-sm mb-6 leading-relaxed">
          {t('offline_desc')}
        </p>

        {isOnline && (
          <div className="w-full flex items-center gap-3 bg-emerald-500/10 border border-emerald-500/20 rounded-2xl p-4 mb-6 animate-in fade-in slide-in-from-bottom-2 duration-300">
            <AlertTriangle className="w-5 h-5 text-emerald-400 shrink-0" />
            <span className="text-emerald-400 text-xs font-semibold text-left">
              {t('network_detected')}
            </span>
          </div>
        )}

        <button
          onClick={handleRetry}
          disabled={checking}
          className="w-full py-4 bg-blue-600 hover:bg-blue-700 disabled:opacity-50 text-white font-bold rounded-2xl transition-all shadow-md flex items-center justify-center gap-3 active:scale-[0.98] select-none touch-manipulation"
        >
          <RefreshCw className={`w-5 h-5 ${checking ? 'animate-spin' : ''}`} />
          {checking ? t('checking_connection') : t('retry_connection')}
        </button>

        <div className="mt-8 text-muted text-[10px] uppercase font-black tracking-wider">
          {t('offline_shell')}
        </div>
      </div>
    </div>
  );
}
